using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.Linq;
public static class CombatV01Setup {
 [MenuItem("Shioka/Combat Test v0.1/Run formula checks")]public static void FormulaChecks(){Debug.Log(CombatV01FormulaChecks.Run());}
 public const string Folder="Assets/CombatPrototype/CombatV01",Profile=Folder+"/CombatTestV01.asset",Scene="Assets/Scenes/CombatFormulaComparison.unity";
 [MenuItem("Shioka/Combat Test v0.1/Install or open")]
 public static void Install(){CanonicalDevelopment.Guard();if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop Play before installing v0.1; current session preserved");if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Save or cancel your unsaved scene first; no scene replaced");System.IO.Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var profile=AssetDatabase.LoadAssetAtPath<CombatV01Profile>(Profile);if(profile==null){var source=Resources.Load<TrainingMoveSet>("TrainingMoveSet");var moves=UnityEngine.Object.Instantiate(source);moves.name="Combat v0.1 moves";var commands=new[]{TrainingCommand.Light,TrainingCommand.Medium,TrainingCommand.Heavy};for(int i=0;i<3;i++){var move=moves.Find(commands[i]);move.attackLevel=260+i*100;move.strength.enabled=false;move.useLevelCurves=false;move.combatDamageMultiplier=1;move.combatChipMultiplier=.1f;move.combatPushbackScale=.001f;}AssetDatabase.CreateAsset(moves,Folder+"/Moves.asset");var hurt=UnityEngine.Object.Instantiate(Resources.Load<TrainingHurtboxProfile>("TrainingHurtboxProfile"));hurt.name="Combat v0.1 hurt parts";foreach(var region in hurt.regions){region.highDefense=region.midDefense=region.lowDefense=100;region.combatPositionCorrection=1;}AssetDatabase.CreateAsset(hurt,Folder+"/Hurtboxes.asset");profile=ScriptableObject.CreateInstance<CombatV01Profile>();profile.moves=moves;profile.hurtboxes=hurt;AssetDatabase.CreateAsset(profile,Profile);}if(!profile.Valid)throw new Exception("Invalid existing v0.1 profile preserved");var scene=EditorSceneManager.OpenScene(Scene);var hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();var session=hud.player.GetComponent<CombatTestV01>();if(session==null)session=Undo.AddComponent<CombatTestV01>(hud.player.gameObject);Undo.RecordObject(session,"Wire v0.1 profile");session.profile=profile;session.player=hud.player;session.opponent=hud.player.opponent;EditorUtility.SetDirty(session);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Selection.activeObject=profile;}
 [MenuItem("Shioka/Combat Test v0.1/Save installed comparison scene")]public static void SaveInstalled(){CanonicalDevelopment.Guard();var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlayingOrWillChangePlaymode||scene.path!=Scene)throw new Exception("Stopped comparison scene required");var hud=UnityEngine.Object.FindAnyObjectByType<TrainingOverlay>();if(hud==null||hud.player.GetComponent<CombatTestV01>()==null||string.IsNullOrEmpty(AssetDatabase.GetAssetPath(hud.player.definition)))throw new Exception("Valid authored actor/profile required; scene preserved");bool saved=EditorSceneManager.SaveScene(scene);Debug.Log("COMBAT_V01_SCENE_SAVED "+saved);}
 [MenuItem("Shioka/Combat Test v0.1/Open playable test")]public static void Open(){if(EditorApplication.isPlayingOrWillChangePlaymode){Debug.LogWarning("Stop Play before opening test");return;}if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Save current scene first; preserved");EditorSceneManager.OpenScene(Scene);}
 public static void Play(){Open();if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().path==Scene&&UnityEngine.Object.FindAnyObjectByType<CombatTestV01>()!=null)EditorApplication.isPlaying=true;}
 [MenuItem("Shioka/Combat Test v0.1/Edit profile") ]public static void Select(){Selection.activeObject=AssetDatabase.LoadAssetAtPath<CombatV01Profile>(Profile);EditorGUIUtility.PingObject(Selection.activeObject);}
 [MenuItem("Shioka/Combat Test v0.1/Edit move geometry") ]public static void Spatial(){if(EditorApplication.isPlayingOrWillChangePlaymode){Debug.LogWarning("Stop Play before spatial editing");return;}var profile=AssetDatabase.LoadAssetAtPath<CombatV01Profile>(Profile);if(profile==null)return;TrainingSpatialAuthoring.Open();var host=UnityEngine.Object.FindAnyObjectByType<TrainingSpatialAuthoring>();host.moves=profile.moves;host.hurtboxes=profile.hurtboxes;host.Reload();Selection.activeGameObject=host.gameObject;}
}
[CustomEditor(typeof(CombatTestV01))]public sealed class CombatV01Inspector:Editor {
 public override void OnInspectorGUI(){DrawDefaultInspector();var session=(CombatTestV01)target;EditorGUILayout.HelpBox("v0.1: edit referenced SOs; Apply authored data then test. Runtime presets never write those SOs. TG gains/FD costs disabled; TRC retains cost. HP/damage fractional; time uses 60 Hz.",MessageType.Info);if(!Application.isPlaying)return;if(GUILayout.Button("Apply authored data / reset HP + TG"))session.ApplyAuthored();if(GUILayout.Button("Reset HP + chosen TG"))session.ResetTest();string[] names={"Equal TG / D100","Attacker0 / defender100 / D100","Attacker0 / defender200 / D100","D180 / TG0","D180 / attacker200 defender80","Attacker100 / defender0 / D100","Equal TG100 / D100"};for(int i=0;i<names.Length;i++)if(GUILayout.Button(names[i]))session.ApplyPreset(i);if(GUILayout.Button("Defender HP=1 (chip KO probe)"))session.opponent.V01SetTestHP(1);if(GUILayout.Button("Toggle training dummy forced guard"))session.opponent.Guarding=!session.opponent.Guarding;foreach(var command in new[]{TrainingCommand.Light,TrainingCommand.Medium,TrainingCommand.Heavy})if(GUILayout.Button("Opponent "+command+" P now")){session.QueueOpponentP(command);ShiokaGameViewFocus.Focus();}foreach(var actor in new[]{session.player,session.opponent})if(actor.V01LastContact.HasValue){var r=actor.V01LastContact.Value;EditorGUILayout.HelpBox(actor.name+" received "+r.outcome+" | A "+r.A.ToString("0.###")+" D "+r.D.ToString("0.###")+" H "+r.H.ToString("0.###")+" B "+r.B.ToString("0.###")+" | TG "+r.attackTG+"/"+r.defenseTG+" | JG age "+r.jgAge+" reduction "+r.jgReduction+" | stop/stun "+r.hitstopFrames+"/"+r.stunFrames,MessageType.None);}EditorGUILayout.LabelField(session.Status);}
}
